package com.tapeverify.copilot.controller;
import com.tapeverify.copilot.dto.*; import com.tapeverify.copilot.repository.*; import com.tapeverify.copilot.entity.LoanBatch; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/batches") public class BatchController {private final LoanBatchRepository batches;private final LoanRepository loans;public BatchController(LoanBatchRepository batches,LoanRepository loans){this.batches=batches;this.loans=loans;}@GetMapping public List<BatchSummaryDto> list(){return batches.findAll().stream().sorted(Comparator.comparing(LoanBatch::getUploadedAt).reversed()).map(this::dto).toList();}@GetMapping("/{id}") public Map<String,Object> detail(@PathVariable String id){LoanBatch b=batches.findById(id).orElseThrow(()->new IllegalArgumentException("Batch not found"));return Map.of("batch",dto(b),"loans",loans.findByBatchId(id).stream().map(x->Map.of("id",x.getId(),"sourceLoanId",java.util.Objects.toString(x.getSourceLoanId(),""),"status",x.getStatus().name(),"sourceRow",x.getSourceRowNumber())).toList());}private BatchSummaryDto dto(LoanBatch b){return BatchSummaryDto.builder().batchId(b.getId()).sourceType(b.getSourceType()).filename(b.getSourceFilename()).uploadedBy(b.getUploadedBy()).uploadedAt(b.getUploadedAt()).status(b.getStatus()).totalRecords(b.getTotalRows()).validRecords(b.getValidRows()).exceptionRecords(b.getExceptionRows()).failedRecords(b.getFailedRows()).build();}}
